$$\begin{array}{l}
  {\left| {P_{1}P_{2}} \right|^{2} = {\left| {P_{1}A} \right|^{2} + \left| \mathit{AB} \right|^{2} + \left| {BP_{2}} \right|^{2}}} \\
  {\phantom{\left| {P_{1}P_{2}} \right|^{2}} = {\left| {x_{2} - x_{1}} \right|^{2} + \left| {y_{2} - y_{1}} \right|^{2} + \left| {z_{2} - z_{1}} \right|^{2}}} \\
  {\phantom{\left| {P_{1}P_{2}} \right|^{2}} = {\left( {x_{2} - x_{1}} \right)^{2} + \left( {y_{2} - y_{1}} \right)^{2} + \left( {z_{2} - z_{1}} \right)^{2}}}
  \end{array}$$

$$\begin{array}{l}
  {{\mathbf{a} \times \mathbf{a}} = \left| \begin{array}{lcc}
  \mathbf{i} & \mathbf{j} & \mathbf{k} \\
  a_{1} & a_{2} & a_{3} \\
  a_{1} & a_{2} & a_{3}
  \end{array} \right|} \\
  {\phantom{\mathbf{a} \times \mathbf{a}} = {\left( {a_{2}a_{3} - a_{3}a_{2}} \right){\mathbf{i}} - \left( {a_{1}a_{3} - a_{3}a_{1}} \right){\mathbf{j}} + \left( {a_{1}a_{2} - a_{2}a_{1}} \right){\mathbf{k}}}} \\
  {\phantom{\mathbf{a} \times \mathbf{a}} = {0\mathbf{i} - 0\mathbf{j} + 0\mathbf{k} = 0}}
  \end{array}$$

$$\begin{array}{l}
  {D = {\left| {{comp}_{\mathbf{n}}\mathbf{b}} \right| = \frac{\left| {\mathbf{n} \cdot \mathbf{b}} \right|}{\left| \mathbf{n} \right|}}} \\
  {\phantom{D} = \frac{\left| {a(x_{1} - x_{0}) + b(y_{1} - y_{0}) + c(z_{1} - z_{0})} \right|}{\sqrt{a^{2} + b^{2} + c^{2}}}} \\
  {\phantom{D} = \frac{\left| {(ax_{1} - by_{1} + cz_{1}) - (ax_{0} - by_{0} + cz_{0})} \right|}{\sqrt{a^{2} + b^{2} + c^{ 2}}}}
  \end{array}$$

